37	     */
38	    private QueryParser(String query) {
39	        Validate.notEmpty(query);
40	        query = query.trim();
41	        this.query = query;
42	        this.tq = new TokenQueue(query);
43	    }
44	
45	    /**
46	     Parse a CSS query into an Evaluator. If you are evaluating the same query repeatedly, it may be more efficient to
47	     parse it once and reuse the Evaluator.
48	
49	     @param query CSS query
50	     @return Evaluator
51	     @see Selector selector query syntax
52	     @throws Selector.SelectorParseException if the CSS query is invalid
53	     */
54	    public static Evaluator parse(String query) {
55	        try (QueryParser p = new QueryParser(query)) {
56	            return p.parse();
57	        } catch (IllegalArgumentException e) {
58	            throw new Selector.SelectorParseException(e.getMessage());
59	        }
60	    }
61	
62	    /**
63	     Parse the query. We use this simplified expression of the grammar:
64	     <pre>
65	     SelectorGroup   ::= Selector (',' Selector)*
66	     Selector        ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
67	     SimpleSequence  ::= [ TypeSelector ] ( ID | Class | Attribute | Pseudo )*
68	     Pseudo           ::= ':' Name [ '(' SelectorGroup ')' ]
69	     Combinator      ::= S+         // descendant (whitespace)
70	     | '>'       // child
71	     | '+'       // adjacent sibling
72	     | '~'       // general sibling
73	     </pre>
74	
75	     See <a href="https://www.w3.org/TR/selectors-4/#grammar">selectors-4</a> for the real thing
76	     */
77	    Evaluator parse() {
78	        Evaluator eval = parseSelectorGroup();
79	        tq.consumeWhitespace();
80	        if (!tq.isEmpty())
81	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
82	        return eval;
83	    }
84	
85	    Evaluator parseSelectorGroup() {
86	        // SelectorGroup. Into an Or if > 1 Selector
87	        Evaluator left = parseSelector();
88	        while (tq.matchChomp(',')) {
89	            Evaluator right = parseSelector();
90	            left = or(left, right);
91	        }
92	        return left;
93	    }
94	
95	    Evaluator parseSelector() {
96	        // Selector ::= [ Combinator ] SimpleSequence ( Combinator SimpleSequence )*
97	        tq.consumeWhitespace();
98	
99	        Evaluator left;
100	        if (tq.matchesAny(Combinators)) {
101	            // e.g. query is "> div"; left side is root element
102	            left = new StructuralEvaluator.Root();
103	        } else {
104	            left = parseSimpleSequence();
105	        }
106	
107	        while (true) {
108	            char combinator = 0;
109	            if (tq.consumeWhitespace())
110	                combinator = ' ';            // maybe descendant?
111	            if (tq.matchesAny(Combinators)) // no, explicit
112	                combinator = tq.consume();
113	            else if (tq.matchesAny(SequenceEnders)) // , - space after simple like "foo , bar"; ) - close of :has()
114	                break;
115	
116	            if (combinator != 0) {
117	                Evaluator right = parseSimpleSequence();
118	                left = combinator(left, combinator, right);
119	            } else {
120	                break;
121	            }
122	        }
123	        return left;
124	    }
125	
126	    Evaluator parseSimpleSequence() {
127	        // SimpleSequence ::= TypeSelector? ( Hash | Class | Pseudo )*
128	        Evaluator left = null;
129	        tq.consumeWhitespace();
130	
131	        // one optional type selector
132	        if (tq.matchesWord() || tq.matches("*|"))
133	            left = byTag();
134	        else if (tq.matchChomp('*'))
135	            left = new Evaluator.AllElements();
136	
137	        // zero or more subclasses (#, ., [)
138	        while(true) {
139	            Evaluator right = parseSubclass();
140	            if (right != null) {
141	                left = and(left, right);
142	            }
143	            else break; // no more simple tokens
144	        }
145	
146	        if (left == null)
147	            throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
148	        return left;
149	    }
150	
151	    static Evaluator combinator(Evaluator left, char combinator, Evaluator right) {
152	        switch (combinator) {
153	            case '>':
154	                ImmediateParentRun run = left instanceof ImmediateParentRun ?
155	                    (ImmediateParentRun) left : new ImmediateParentRun(left);
156	                run.add(right);
157	                return run;
158	            case ' ':
159	                return and(new StructuralEvaluator.Ancestor(left), right);
160	            case '+':
161	                return and(new StructuralEvaluator.ImmediatePreviousSibling(left), right);
162	            case '~':
163	                return and(new StructuralEvaluator.PreviousSibling(left), right);
164	            default:
165	                throw new Selector.SelectorParseException("Unknown combinator '%s'", combinator);
166	        }
167	    }
168	
169	    @Nullable Evaluator parseSubclass() {
170	        //  Subclass: ID | Class | Attribute | Pseudo
171	        if      (tq.matchChomp('#'))    return byId();
172	        else if (tq.matchChomp('.'))    return byClass();
173	        else if (tq.matches('['))       return byAttribute();
174	        else if (tq.matchChomp("::"))   return parseNodeSelector(); // ::comment etc
175	        else if (tq.matchChomp(':'))    return parsePseudoSelector();
176	        else                            return null;
177	    }
178	
179	    /** Merge two evals into an Or. */
180	    static Evaluator or(Evaluator left, Evaluator right) {
181	        if (left instanceof CombiningEvaluator.Or) {
182	            ((CombiningEvaluator.Or) left).add(right);
183	            return left;
184	        }
185	        return new CombiningEvaluator.Or(left, right);
186	    }
187	
188	    /** Merge two evals into an And. */
189	    static Evaluator and(@Nullable Evaluator left, Evaluator right) {
190	        if (left == null) return right;
191	        if (left instanceof CombiningEvaluator.And) {
192	            ((CombiningEvaluator.And) left).add(right);
193	            return left;
194	        }
195	        return new CombiningEvaluator.And(left, right);
196	    }
197	
198	    private Evaluator parsePseudoSelector() {
199	        final String pseudo = tq.consumeCssIdentifier();
200	        switch (pseudo) {
201	            case "lt":
202	                return new Evaluator.IndexLessThan(consumeIndex());
203	            case "gt":
204	                return new Evaluator.IndexGreaterThan(consumeIndex());
205	            case "eq":
206	                return new Evaluator.IndexEquals(consumeIndex());
207	            case "has":
208	                return has();
209	            case "is":
210	                return is();
211	            case "contains":
212	                return contains(false);
213	            case "containsOwn":
214	                return contains(true);
215	            case "containsWholeText":
216	                return containsWholeText(false);
217	            case "containsWholeOwnText":
218	                return containsWholeText(true);
219	            case "containsData":
220	                return containsData();
221	            case "matches":
222	                return matches(false);
223	            case "matchesOwn":
224	                return matches(true);
225	            case "matchesWholeText":
226	                return matchesWholeText(false);
227	            case "matchesWholeOwnText":
228	                return matchesWholeText(true);
229	            case "not":
230	                return not();
231	            case "nth-child":
232	                return cssNthChild(false, false);
233	            case "nth-last-child":
234	                return cssNthChild(true, false);
235	            case "nth-of-type":
236	                return cssNthChild(false, true);
237	            case "nth-last-of-type":
238	                return cssNthChild(true, true);
239	            case "first-child":
240	                return new Evaluator.IsFirstChild();
241	            case "last-child":
242	                return new Evaluator.IsLastChild();
243	            case "first-of-type":
244	                return new Evaluator.IsFirstOfType();
245	            case "last-of-type":
246	                return new Evaluator.IsLastOfType();
247	            case "only-child":
248	                return new Evaluator.IsOnlyChild();
249	            case "only-of-type":
250	                return new Evaluator.IsOnlyOfType();
251	            case "empty":
252	                return new Evaluator.IsEmpty();
253	            case "blank":
254	                return new NodeEvaluator.BlankValue();
255	            case "root":
256	                return new Evaluator.IsRoot();
257	            case "scope":
258	                return new StructuralEvaluator.Scope();
259	            case "matchText": {
260	                @SuppressWarnings("deprecation") // :matchText remains supported until its scheduled removal.
261	                Evaluator.MatchText matchText = new Evaluator.MatchText();
262	                return matchText;
263	            }
264	            default:
265	                throw new Selector.SelectorParseException("Could not parse query '%s': unexpected token at '%s'", query, tq.remainder());
266	        }
267	    }
268	
269	    // ::comment etc
270	    private Evaluator parseNodeSelector() {
271	        final String pseudo = tq.consumeCssIdentifier();
272	        inNodeContext = true;  // Enter node context
273	
274	        Evaluator left;
275	        switch (pseudo) {
276	            case "node":
277	                left = new NodeEvaluator.InstanceType(Node.class, pseudo);
278	                break;
279	            case "leafnode":
280	                left = new NodeEvaluator.InstanceType(LeafNode.class, pseudo);
281	                break;
282	            case "text":
283	                left = new NodeEvaluator.InstanceType(TextNode.class, pseudo);
284	                break;
285	            case "comment":
286	                left = new NodeEvaluator.InstanceType(Comment.class, pseudo);
287	                break;
288	            case "data":
289	                left = new NodeEvaluator.InstanceType(DataNode.class, pseudo);
290	                break;
291	            case "cdata":
292	                left = new NodeEvaluator.InstanceType(CDataNode.class, pseudo);
293	                break;
294	            default:
295	                throw new Selector.SelectorParseException(
296	                    "Could not parse query '%s': unknown node type '::%s'", query, pseudo);
297	        }
298	
299	        // Handle following subclasses in node context (like ::comment:contains())
300	        Evaluator right;
301	        while ((right = parseSubclass()) != null) {
302	            left = and(left, right);
303	        }
304	
305	        inNodeContext = false;
306	        return left;
307	    }
308	
309	    private Evaluator byId() {
310	        String id = tq.consumeCssIdentifier();
311	        Validate.notEmpty(id);
312	        return new Evaluator.Id(id);
313	    }
314	
315	    private Evaluator byClass() {
316	        String className = tq.consumeCssIdentifier();
317	        Validate.notEmpty(className);
318	        return new Evaluator.Class(className.trim());
319	    }
320	
321	    private Evaluator byTag() {
322	        // todo - these aren't dealing perfectly with case sensitivity. For case sensitive parsers, we should also make
323	        // the tag in the selector case-sensitive (and also attribute names). But for now, normalize (lower-case) for
324	        // consistency - both the selector and the element tag
325	        String tagName = normalize(tq.consumeElementSelector());
326	        Validate.notEmpty(tagName);
327	
328	        // namespaces:
329	        if (tagName.startsWith("*|")) { // namespaces: wildcard match equals(tagName) or ending in ":"+tagName
330	            String plainTag = tagName.substring(2); // strip *|
331	            return new CombiningEvaluator.Or(
332	                new Evaluator.Tag(plainTag),
333	                new Evaluator.TagEndsWith(":" + plainTag)
334	            );
335	        } else if (tagName.endsWith("|*")) { // ns|*
336	            String ns = tagName.substring(0, tagName.length() - 2) + ":"; // strip |*, to ns:
337	            return new Evaluator.TagStartsWith(ns);
338	        } else if (tagName.contains("|")) { // flip "abc|def" to "abc:def"
339	            tagName = tagName.replace("|", ":");
340	        }
341	
342	        return new Evaluator.Tag(tagName);
343	    }
344	
345	    private Evaluator byAttribute() {
346	        try (TokenQueue cq = new TokenQueue(tq.chompBalanced('[', ']'))) {
347	            return evaluatorForAttribute(cq);
348	        }
349	    }
350	
351	    private Evaluator evaluatorForAttribute(TokenQueue cq) {
352	        String key = cq.consumeToAny(AttributeEvals); // eq, not, start, end, contain, match, (no val)
353	        key = normalize(key);
354	        Validate.notEmpty(key);
355	        Validate.isFalse(key.equals("abs:"), "Absolute attribute key must have a name");
356	        cq.consumeWhitespace();
357	        final Evaluator eval;
358	
359	        if (cq.isEmpty()) {
360	            if (key.startsWith("^"))
361	                eval = new Evaluator.AttributeStarting(key.substring(1));
362	            else if (key.equals("*")) // any attribute
363	                eval = new Evaluator.AttributeStarting("");
364	            else
365	                eval = new Evaluator.Attribute(key);
366	        } else {
367	            if (cq.matchChomp('='))
368	                eval = new Evaluator.AttributeWithValue(key, cq.remainder());
369	            else if (cq.matchChomp("!="))
370	                eval = new Evaluator.AttributeWithValueNot(key, cq.remainder());
371	            else if (cq.matchChomp("^="))
372	                eval = new Evaluator.AttributeWithValueStarting(key, cq.remainder());
373	            else if (cq.matchChomp("$="))
374	                eval = new Evaluator.AttributeWithValueEnding(key, cq.remainder());
375	            else if (cq.matchChomp("*="))
376	                eval = new Evaluator.AttributeWithValueContaining(key, cq.remainder());
377	            else if (cq.matchChomp("~="))
378	                eval = new Evaluator.AttributeWithValueMatching(key, Regex.compile(cq.remainder()));
379	            else
380	                throw new Selector.SelectorParseException(
381	                    "Could not parse attribute query '%s': unexpected token at '%s'", query, cq.remainder());
382	        }
383	        return eval;
384	    }
385	
386	    //pseudo selectors :first-child, :last-child, :nth-child, ...
387	    private static final Pattern NthStepOffset = Pattern.compile("(([+-])?(\\d+)?)n(\\s*([+-])?\\s*\\d+)?", Pattern.CASE_INSENSITIVE);
388	    private static final Pattern NthOffset = Pattern.compile("([+-])?(\\d+)");
389	
390	    private Evaluator cssNthChild(boolean last, boolean ofType) {
391	        String raw = consumeParens(); // arg is like "odd", or "-n+2", within nth-child(odd), optionally followed by " of S"
392	        final int ofIdx = indexOfOfClause(raw);
393	        final String arg = normalize(ofIdx >= 0 ? raw.substring(0, ofIdx) : raw);
394	        final boolean hasOf = ofIdx >= 0;
395	
396	        if (hasOf && ofType)
397	            throw new Selector.SelectorParseException(
398	                "Could not parse query '%s': 'of S' is only supported by :nth-child and :nth-last-child", query);
399	
400	        final int step, offset;
401	        if ("odd".equals(arg)) {
402	            step = 2;
403	            offset = 1;
404	        } else if ("even".equals(arg)) {
405	            step = 2;
406	            offset = 0;
407	        } else {
408	            Matcher stepOffsetM, stepM;
409	            if ((stepOffsetM = NthStepOffset.matcher(arg)).matches()) {
410	                if (stepOffsetM.group(3) != null) // has digits, like 3n+2 or -3n+2
411	                    step = Integer.parseInt(stepOffsetM.group(1).replaceFirst("^\\+", ""));
412	                else // no digits, might be like n+2, or -n+2. if group(2) == "-", it’s -1;
413	                    step = "-".equals(stepOffsetM.group(2)) ? -1 : 1;
414	                offset =
415	                    stepOffsetM.group(4) != null ? Integer.parseInt(stepOffsetM.group(4).replaceFirst("^\\+", "")) : 0;
416	            } else if ((stepM = NthOffset.matcher(arg)).matches()) {
417	                step = 0;
418	                offset = Integer.parseInt(stepM.group().replaceFirst("^\\+", ""));
419	            } else {
420	                throw new Selector.SelectorParseException("Could not parse nth-index '%s': unexpected format", arg);
421	            }
422	        }
423	
424	        if (hasOf) {
425	            String subQuery = raw.substring(ofIdx + 2).trim(); // skip the "of" keyword
426	            Validate.notEmpty(subQuery, ":nth-child(An+B of S) selector S must not be empty");
427	            Evaluator selector = parse(subQuery); // a comma-separated complex selector list; validates the full grammar
428	            return new Evaluator.IsNthChildOf(step, offset, last, selector);
429	        }
430	
431	        return ofType
432	            ? (last ? new Evaluator.IsNthLastOfType(step, offset) : new Evaluator.IsNthOfType(step, offset))
433	            : (last ? new Evaluator.IsNthLastChild(step, offset) : new Evaluator.IsNthChild(step, offset));
434	    }
435	
436	    /**
437	     Finds the index of the {@code of} keyword separating An+B from the selector list in an
438	     {@code :nth-child(An+B of S)} argument. The keyword must be bounded on both sides by whitespace, and is not
439	     matched inside quoted strings (so attribute values containing " of " are preserved).
440	     @return the index of the 'o' in 'of', or -1 if there is no of clause
441	     */
442	    private static int indexOfOfClause(String arg) {
443	        boolean inSingle = false;
444	        boolean inDouble = false;
445	        boolean prevEscaped = false;
446	        for (int i = 0; i < arg.length(); i++) {
447	            char c = arg.charAt(i);
448	            if (c == '\\' && i + 1 < arg.length()) {
449	                i++; // skip the escaped char
450	                prevEscaped = true;
451	                continue;
452	            }
453	            if (!inDouble && c == '\'')
454	                inSingle = !inSingle;
455	            else if (!inSingle && c == '"')
456	                inDouble = !inDouble;
457	
458	            if (!inSingle && !inDouble && !prevEscaped
459	                && i > 0 && StringUtil.isWhitespace(arg.charAt(i - 1))
460	                && arg.regionMatches(true, i, "of", 0, 2)
461	                && i + 2 < arg.length() && StringUtil.isWhitespace(arg.charAt(i + 2))) {
462	                return i;
463	            }
464	            prevEscaped = false;
465	        }
466	        return -1;
467	    }
468	
469	    private String consumeParens() {
470	        return tq.chompBalanced('(', ')');
471	    }
472	
473	    private int consumeIndex() {
474	        String index = consumeParens().trim();
475	        Validate.isTrue(StringUtil.isNumeric(index), "Index must be numeric");
476	        return Integer.parseInt(index);
477	    }
478	
479	    // pseudo selector :has(el)
480	    private Evaluator has() {
481	        return parseNested(StructuralEvaluator.Has::new, ":has() must have a selector");
482	    }
483	
484	    // pseudo selector :is()
485	    private Evaluator is() {
486	        return parseNested(StructuralEvaluator.Is::new, ":is() must have a selector");
487	    }
488	
489	    private Evaluator parseNested(Function<Evaluator, Evaluator> func, String err) {
490	        Validate.isTrue(tq.matchChomp('('), err);
491	        Evaluator eval = parseSelectorGroup();
492	        Validate.isTrue(tq.matchChomp(')'), err);
493	        return func.apply(eval);
494	    }
495	
496	    // pseudo selector :contains(text), containsOwn(text)
497	    private Evaluator contains(boolean own) {
498	        String query = own ? ":containsOwn" : ":contains";
499	        String searchText = TokenQueue.unescape(consumeParens());
500	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
501	
502	        if (inNodeContext)
503	            return new NodeEvaluator.ContainsValue(searchText);
504	
505	        return own
506	            ? new Evaluator.ContainsOwnText(searchText)
507	            : new Evaluator.ContainsText(searchText);
508	    }
509	
510	    private Evaluator containsWholeText(boolean own) {
511	        String query = own ? ":containsWholeOwnText" : ":containsWholeText";
512	        String searchText = TokenQueue.unescape(consumeParens());
513	        Validate.notEmpty(searchText, query + "(text) query must not be empty");
514	        return own
515	            ? new Evaluator.ContainsWholeOwnText(searchText)
516	            : new Evaluator.ContainsWholeText(searchText);
517	    }
518	
519	    // pseudo selector :containsData(data)
520	    private Evaluator containsData() {
521	        String searchText = TokenQueue.unescape(consumeParens());
522	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
523	        return new Evaluator.ContainsData(searchText);
524	    }
525	
526	    // :matches(regex), matchesOwn(regex)
527	    private Evaluator matches(boolean own) {
528	        String query = own ? ":matchesOwn" : ":matches";
529	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
530	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
531	        Regex pattern = Regex.compile(regex);
532	
533	        if (inNodeContext)
534	            return new NodeEvaluator.MatchesValue(pattern);
535	
536	        return own
537	            ? new Evaluator.MatchesOwn(pattern)
538	            : new Evaluator.Matches(pattern);
539	    }
540	
541	    // :matches(regex), matchesOwn(regex)
542	    private Evaluator matchesWholeText(boolean own) {
543	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
544	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
545	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
546	
547	        Regex pattern = Regex.compile(regex);
548	        return own
549	            ? new Evaluator.MatchesWholeOwnText(pattern)
550	            : new Evaluator.MatchesWholeText(pattern);
551	    }
552	
553	    // :not(selector)
554	    private Evaluator not() {
555	        String subQuery = consumeParens();
556	        Validate.notEmpty(subQuery, ":not(selector) subselect must not be empty");
557	
558	        return new StructuralEvaluator.Not(parse(subQuery));
559	    }
560	
561	    @Override
562	    public String toString() {
563	        return query;
564	    }
565	
566	    @Override
567	    public void close() {
568	        tq.close();
569	    }
570	}
