565	    public static abstract class CssNthEvaluator extends Evaluator {
566	        /** Step */
567	        protected final int a;
568	        /** Offset */
569	        protected final int b;
570	
571	        public CssNthEvaluator(int step, int offset) {
572	            this.a = step;
573	            this.b = offset;
574	        }
575	
576	        public CssNthEvaluator(int offset) {
577	            this(0, offset);
578	        }
579	
580	        @Override
581	        public boolean matches(Element root, Element element) {
582	            final Element p = element.parent();
583	            if (p == null || (p instanceof Document)) return false;
584	
585	            final int pos = calculatePosition(root, element);
586	            return matchesNth(a, b, pos);
587	        }
588	
589	        /**
590	         Tests if a 1-based sibling position matches the An+B periodic formula.
591	         @param a the step
592	         @param b the offset
593	         @param pos the 1-based position
594	         @return true if it matches
595	         */
596	        static boolean matchesNth(int a, int b, int pos) {
597	            if (a == 0) return pos == b;
598	            return (pos - b) * a >= 0 && (pos - b) % a == 0;
599	        }
600	
601	        @Override
602	        public String toString() {
603	            String format =
604	                (a == 0) ? ":%s(%3$d)"    // only offset (b)
605	                : (b == 0) ? ":%s(%2$dn)" // only step (a)
606	                : ":%s(%2$dn%3$+d)";      // step, offset
607	            return String.format(format, getPseudoClass(), a, b);
608	        }
609	
610	        protected abstract String getPseudoClass();
611	
612	        protected abstract int calculatePosition(Element root, Element element);
613	    }
