659	    /**
660	     * css pseudo class nth-of-type
661	     *
662	     */
663	    public static class IsNthOfType extends CssNthEvaluator {
664	        public IsNthOfType(int step, int offset) {
665	            super(step, offset);
666	        }
667	
668	        @Override protected int calculatePosition(Element root, Element element) {
669	            Element parent = element.parent();
670	            if (parent == null)
671	                return 0;
672	
673	            int pos = 0;
674	            final int size = parent.childNodeSize();
675	            for (int i = 0; i < size; i++) {
676	                Node node = parent.childNode(i);
677	                if (node.normalName().equals(element.normalName())) pos++;
678	                if (node == element) break;
679	            }
680	            return pos;
681	        }
682	
683	        @Override
684	        protected String getPseudoClass() {
685	            return "nth-of-type";
686	        }
687	    }
