689	    public static class IsNthLastOfType extends CssNthEvaluator {
690	        public IsNthLastOfType(int step, int offset) {
691	            super(step, offset);
692	        }
693	
694	        @Override
695	        protected int calculatePosition(Element root, Element element) {
696	            Element parent = element.parent();
697	            if (parent == null)
698	                return 0;
699	
700	            int pos = 0;
701	            Element next = element;
702	            while (next != null) {
703	                if (next.normalName().equals(element.normalName()))
704	                    pos++;
705	                next = next.nextElementSibling();
706	            }
707	            return pos;
708	        }
709	
710	        @Override
711	        protected String getPseudoClass() {
712	            return "nth-last-of-type";
713	        }
714	    }
