716	    /**
717	     * css pseudo class :nth-child(An+B of S) and :nth-last-child(An+B of S). Only sibling elements that match the
718	     * selector list {@code S} are candidates and counted; the position is computed in document order (or reverse, for
719	     * nth-last-child).
720	     * @see <a href="https://www.w3.org/TR/selectors-4/#nth-child-pseudo">:nth-child(An+B of S)</a>
721	     */
722	    public static final class IsNthChildOf extends CssNthEvaluator {
723	        private final Evaluator selector;
724	        private final boolean last;
725	
726	        public IsNthChildOf(int step, int offset, boolean last, Evaluator selector) {
727	            super(step, offset);
728	            this.last = last;
729	            this.selector = selector;
730	        }
731	
732	        @Override
733	        public boolean matches(Element root, Element element) {
734	            final Element p = element.parent();
735	            if (p == null || (p instanceof Document)) return false;
736	            if (!selector.matches(root, element)) return false; // candidates must match S
737	
738	            return matchesNth(a, b, calculatePosition(root, element));
739	        }
740	
741	        @Override
742	        protected int calculatePosition(Element root, Element element) {
743	            int pos = 0;
744	            if (last) {
745	                for (Element sib = element; sib != null; sib = sib.nextElementSibling()) {
746	                    if (selector.matches(root, sib)) pos++;
747	                }
748	            } else {
749	                final Element p = element.parent();
750	                for (Element sib = p.firstElementChild(); sib != null; sib = sib.nextElementSibling()) {
751	                    if (selector.matches(root, sib)) pos++;
752	                    if (sib == element) break;
753	                }
754	            }
755	            return pos;
756	        }
757	
758	        @Override
759	        protected String getPseudoClass() {
760	            return last ? "nth-last-child" : "nth-child";
761	        }
762	
763	        @Override protected int cost() {
764	            return 5 + selector.cost();
765	        }
766	
767	        @Override protected void reset() {
768	            selector.reset();
769	            super.reset();
770	        }
771	
772	        @Override
773	        public String toString() {
774	            String format =
775	                (a == 0) ? ":%s(%3$d of %4$s)"     // only offset (b)
776	                : (b == 0) ? ":%s(%2$dn of %4$s)"  // only step (a)
777	                : ":%s(%2$dn%3$+d of %4$s)";       // step, offset
778	            return String.format(format, getPseudoClass(), a, b, selector);
779	        }
780	    }
