666	    @Test public void testHasRelativeScope() {
667	        // relative selectors in :has are anchored to the tested element; :scope is the explicit form of that anchor
668	        Document doc = Jsoup.parse(
669	            "<article id=a><h1></h1><h2></h2><p><b></b><i></i></p></article>" +
670	            "<article id=z><h1></h1><p></p><b></b><i></i></article>");
671	
672	        assertSelectedIds(doc.select("article:has(> h1 + h2)"), "a");
673	        assertSelectedIds(doc.select("article:has(> b + i)"), "z");
674	        assertSelectedIds(doc.select("article:has(p:has(> b + i))"), "a");
675	        assertSelectedIds(doc.select("article:has(:scope > p > b + i)"), "a");
676	        assertSelectedIds(doc.select("article:has(+ article)"), "a");
677	
678	        // css escapes in pseudo-class names are equivalent to the unescaped names
679	        assertSelectedIds(doc.select("article:h\\61 s(> h1 + h2)"), "a");
680	        assertSelectedIds(doc.select("article:h\\61 s(:sc\\6f pe > p > b + i)"), "a");
681	
682	        // explicit :scope is equivalent to the implicit anchor of a leading combinator
683	        assertSelectedIds(doc.select("article:has(:scope > h1 + h2)"), "a");
684	        assertSelectedIds(doc.select("article:has(:scope + article)"), "a");
