import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Elements;

public class Check2 {
    static void t(String html, String css) {
        Document doc = Jsoup.parse(html);
        try {
            Elements els = doc.select(css);
            StringBuilder sb = new StringBuilder();
            els.forEach(e -> sb.append("#").append(e.id().isEmpty() ? e.tagName() : e.id()).append(" "));
            System.out.println(css + " => [" + sb.toString().trim() + "]");
        } catch (Exception e) {
            System.out.println(css + " => ERROR " + e.getClass().getSimpleName() + ": " + e.getMessage());
        }
    }
    public static void main(String[] args) {
        // leaf chain inside subtree: leading + adjacent to a text node
        t("<article id=a><h1></h1>txt<!--c--></article>", "article:has(h1 + ::comment)");
        // :is container with leading sibling combinator (boundary: should not escape)
        t("<article id=a></article><p></p>", "article:has(:is(+ p))");
        // compound :scope anchor
        t("<article id=a></article><p></p>", "article:has(:scope:not(.x) + p)");
        // parse errors
        t("<a>", "a:has()");
        t("<a>", "a:has(+)");
        t("<a>", "a:has(b");
    }
}
