import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.*;
import java.lang.reflect.*;

public class Debug2 {
    public static void main(String[] args) throws Exception {
        Document doc = Jsoup.parse("<article id=a></article><article id=b><p></p></article><article id=c></article>");
        for (String css : new String[]{"article:has(+ article > p)", "article:has(:scope > p > b + i)", "article:has(+ ::comment)"}) {
            Evaluator ev = QueryParser.parse(css);
            // find Has instance
            Evaluator has = find(ev, StructuralEvaluator.Has.class);
            if (has != null) {
                Field f = StructuralEvaluator.Has.class.getDeclaredField("wantsSiblings");
                f.setAccessible(true);
                System.out.println(css + " wantsSiblings=" + java.util.Arrays.toString((boolean[]) f.get(has)));
            }
            System.out.println("  result=" + doc.select(css).size());
        }
    }
    static Evaluator find(Evaluator ev, Class<?> type) {
        if (type.isInstance(ev)) return ev;
        if (ev instanceof CombiningEvaluator) {
            for (Evaluator e : ((CombiningEvaluator) ev).evaluators) {
                Evaluator r = find(e, type);
                if (r != null) return r;
            }
        }
        if (ev instanceof StructuralEvaluator) {
            return find(((StructuralEvaluator) ev).evaluator, type);
        }
        return null;
    }
}
