        return doc.select(css).size();
    }
    public static void main(String[] args) {
        // compiled evaluator reuse across docs
        Evaluator ev = QueryParser.parse("article:has(~ ::comment)");
        Document d1 = Jsoup.parse("<article id=a></article><p></p><!--c-->");
        Document d2 = Jsoup.parse("<article id=a></article><p></p>");
        System.out.println("reuse: " + (Selector.select(ev, d1).size() == 1 && Selector.select(ev, d2).size() == 0));

        // ::data / ::cdata leaves count in the full node sequence too
        Document d3 = Jsoup.parse("<article id=a></article><style>.x{}</style><b></b>");
        System.out.println("data skip ~: " + t(d3, "article:has(~ b)"));         // 1
        Document d4 = Jsoup.parse("<article id=a></article><style>.x{}</style>");
        System.out.println("data adjacent: " + t(d4, "article:has(+ ::data)")); // 1
        Document d5 = Jsoup.parse("<article id=a></article>x<style>.x{}</style>");
        System.out.println("data blocked: " + t(d5, "article:has(+ ::data)"));  // 0
    }
}
