        Document d = Jsoup.parse("<article id=a></article><style>.x{}</style><b></b>");
        System.out.println(d.select("article:has(+ style:has(> ::data) + b)").size()); // 1
        System.out.println(d.select("article:has(+ style + b)").size());               // 1
        // comment between style and b, element chain ignores it
        Document d2 = Jsoup.parse("<article id=a></article><style></style><!--c--><b></b>");
        System.out.println(d2.select("article:has(+ style + b)").size());              // 1
        System.out.println(d2.select("article:has(+ style + ::comment + b)").size());  // 1
        System.out.println(d2.select("article:has(+ style + ::comment)").size());      // 1
    }
}
